const { chromium } = require('playwright');
(async()=>{
  const browser = await chromium.launch({headless:true,args:['--use-angle=swiftshader']});
  const page = await browser.newPage({viewport:{width:1280,height:720}});
  page.on('console', msg => console.log('console:', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('pageerror:', err.message));
  await page.goto('http://localhost:3002', {waitUntil:'load', timeout: 20000});
  await page.waitForTimeout(2000);
  const title = await page.title();
  console.log('title=', title);
  const bodyText = await page.locator('body').innerText();
  console.log('body snippet=', bodyText.slice(0,400));
  const hasCanvas = await page.locator('canvas').count();
  console.log('canvas count=', hasCanvas);
  const gameState = await page.evaluate(() => {
    const c = document.getElementById('game');
    const ctx = c.getContext('2d');
    const d = ctx.getImageData(300,200,1,1).data;
    return { width:c.width, height:c.height, sample:d.slice(0,4) };
  });
  console.log('gameState=', gameState);
  await page.screenshot({ path: '/tmp/opencode/latest.jpg', type:'jpeg', quality:80, fullPage:false });
  console.log('saved /tmp/opencode/latest.jpg');
  await browser.close();
})();
